// The spoken narration of the tour: what is said and when.
// The speech is generated by VoiceStudio (see tools/narrate.ts) into public/narration/<id>.wav.
// This file imports only the plain schedule, so both the video and the generator script can read it.
import { sceneStart, type SceneId } from "./schedule.ts";

export interface NarrationLine {
  id: string;
  scene: SceneId;
  /** Start in seconds from the beginning of the scene (for the classic scene: of the part that is shown). */
  at: number;
  /** What is said; written so that it is pronounced right (e.g. "Control K", not "Ctrl+K"). */
  text: string;
  /** Speed of the speech, 1 = normal; used to fit a line into the time it has. */
  speed?: number;
}

/** Start of the line in the video, seconds. */
export const startOf = (line: NarrationLine): number => Number((sceneStart(line.scene) + line.at).toFixed(2));

export const VOICE = {
  /** The English demo voice that comes with VoiceStudio (profile id). */
  profile: "demo0001",
  language: "en",
  /** The same seed and text give the same speech, so a re-render does not change the voice. */
  seed: 7,
};

